import assert from 'node:assert/strict';
/** Shared assertions run through real Node HTTP and actual workerd production routing, never a mocked content handler. */
export async function exerciseBlockForest({request,owner,person,workspaceId,inspect,replacePerson}){
 const base='/api/content/workspaces/'+workspaceId,pages=base+'/pages',ok=async(response,status=200)=>{assert.equal(response.status,status,await response.clone().text());return response.json();},call=(path,body,account=owner)=>request(path,{method:body?'POST':'GET',body,account});let revision=0;
 const create=async(title,blocks)=>{const result=await ok(await call(pages,{expectedRevision:revision,title,blocks}),201);revision=result.revision;return result;};
 const reference=await create('Reference',[]),target=await create('Target',[{id:'target-parent',type:'quote',data:{text:'Parent'},children:[{id:'existing',type:'paragraph',data:{text:'Existing'}}]}]);
 const source=await create('Source',[{id:'first',type:'paragraph',data:{text:'Peer ref date',future:{kept:true}},children:[{id:'first-child',type:'quote',data:{text:'Nested'}}]},{id:'layout',type:'columns',children:[{id:'left',type:'column',children:[{id:'column-body',type:'paragraph',data:{text:'Column body'}}]},{id:'right',type:'column',children:[]}]},{id:'tail',type:'paragraph',data:{text:'Tail'}},{id:'keep',type:'paragraph',data:{text:'Keep'}}]);
 for(const page of [source,target]){const result=await ok(await call(pages+'/'+page.page.id+'/grants',{expectedRevision:revision,accountId:person.id,permission:'viewer'}));revision=result.revision;}
 const blocks=structuredClone(source.document.blocks);blocks[0].data={...blocks[0].data,marks:[{start:0,end:4,styles:['bold']}],links:[{start:5,end:8,label:'ref',pageId:reference.page.id}],mentions:[{kind:'person',start:0,end:4,accountId:person.id},{kind:'page',start:5,end:8,pageId:reference.page.id},{kind:'date',start:9,end:13,date:'2026-10-17'}]};
 const patched=await ok(await request(pages+'/'+source.page.id,{method:'PATCH',account:owner,body:{expectedRevision:revision,expectedVersion:1,blocks}}));revision=patched.revision;
 const rooms=[];for(const page of [source,target]){const room=await ok(await call(pages+'/'+page.page.id+'/room/open',{expectedRevision:revision}),201);revision=room.revision;rooms.push({pageId:page.page.id,...room});}
 const before=await inspect(),path=pages+'/'+source.page.id+'/blocks/move',intent={expectedRevision:revision,expectedVersion:2,targetPageId:target.page.id,targetExpectedVersion:1,blockIds:['tail','first-child','column-body','layout','first','first'],parentBlockId:'target-parent',index:1};
 const invalid=await call(path,{...intent,blockIds:['first','missing']});assert.equal(invalid.status,404);assert.deepEqual(await inspect(),before);
 const moved=await ok(await call(path,intent));assert.deepEqual(moved,{revision:revision+1,blockIds:['first','layout','tail'],sourcePageId:source.page.id,targetPageId:target.page.id,sourceVersion:3,targetVersion:2});revision=moved.revision;
 const raw=await inspect(),sourceBefore=before.payload.pages.find(item=>item.page.id===source.page.id),sourceAfter=raw.payload.pages.find(item=>item.page.id===source.page.id),targetAfter=raw.payload.pages.find(item=>item.page.id===target.page.id);
 assert.deepEqual(sourceAfter.document.blocks,[sourceBefore.document.blocks[3]]);assert.deepEqual(targetAfter.document.blocks[0].children.slice(1),sourceBefore.document.blocks.slice(0,3));assert.equal(raw.payload.rooms.length,0);assert.equal(raw.payload.history.filter(item=>item.kind==='block-move').length,2);
 const restricted=await ok(await request(pages+'/'+target.page.id,{account:person})),hiddenReference=restricted.document.blocks[0].children[1].data.mentions[1];assert.equal(hiddenReference.unavailable,true);assert.equal(Object.hasOwn(hiddenReference,'pageId'),false);
 for(const room of rooms){const response=await request(pages+'/'+room.pageId+'/room',{account:owner,headers:{'X-Yumunio-Room-Ticket':room.ticket}});assert.equal(response.status,409);}
 assert.equal((await call(path,intent)).status,409);assert.deepEqual(await inspect(),raw);
 const extracted=await ok(await call(pages+'/'+target.page.id+'/blocks/move',{expectedRevision:revision,expectedVersion:2,targetPageId:source.page.id,targetExpectedVersion:3,blockIds:['column-body'],parentBlockId:null,index:1}));revision=extracted.revision;
 const emptied=await inspect(),layout=emptied.payload.pages.find(item=>item.page.id===target.page.id).document.blocks[0].children.find(block=>block.id==='layout');assert.deepEqual(layout.children.map(column=>column.children),[[],[]]);
 await replacePerson();const denied=await call(pages+'/'+target.page.id+'/blocks/move',{expectedRevision:revision,expectedVersion:3,targetPageId:source.page.id,targetExpectedVersion:4,blockIds:['tail','first'],parentBlockId:null,index:2});assert.equal(denied.status,404);assert.deepEqual(await inspect(),emptied);
 const legacy=await ok(await call(path,{expectedRevision:revision,expectedVersion:4,targetPageId:target.page.id,targetExpectedVersion:3,blockId:'column-body',parentBlockId:null,index:1}));assert.equal(legacy.blockId,'column-body');assert.equal('blockIds'in legacy,false);assert.equal(legacy.revision,revision+1);assert.equal(legacy.sourceVersion,5);assert.equal(legacy.targetVersion,4);
 const saved=await ok(await request(pages+'/'+target.page.id,{account:owner}));assert.equal(saved.document.blocks[1].id,'column-body');assert.equal(saved.document.blocks[0].children[1].data.mentions[0].unavailable,true);assert.equal(Object.hasOwn(saved.document.blocks[0].children[1].data.mentions[0],'accountId'),false);
 return{revision:legacy.revision,sourcePageId:source.page.id,targetPageId:target.page.id};
}
